import { app, BrowserWindow, dialog, ipcMain } from "electron";
import { readFileSync, writeFileSync, existsSync } from "fs";
import path from "path";
import * as child_process from "child_process";
import * as dotenv from "dotenv";
import { promisify } from "util";
import { error } from "console";
dotenv.config();
const execAsync = promisify(child_process.exec);
// This allows TypeScript to pick up the magic constants that's auto-generated by Forge's Webpack
// plugin that tells the Electron app where to look for the Webpack-bundled app code (depending on
// whether you're running in development or production).
declare const MAIN_WINDOW_WEBPACK_ENTRY: string;
declare const MAIN_WINDOW_PRELOAD_WEBPACK_ENTRY: string;

// Handle creating/removing shortcuts on Windows when installing/uninstalling.
if (require("electron-squirrel-startup")) {
  app.quit();
}

const createWindow = (): void => {
  // Create the browser window.
  const mainWindow = new BrowserWindow({
    height: 600,
    width: 800,
    webPreferences: {
      preload: MAIN_WINDOW_PRELOAD_WEBPACK_ENTRY,
    },
    icon: "./public/favicon.ico",
    autoHideMenuBar: true,
  });

  // and load the index.html of the app.
  mainWindow.loadURL(MAIN_WINDOW_WEBPACK_ENTRY);

  // Open the DevTools.
  // mainWindow.webContents.openDevTools();

  mainWindow.webContents.session.on(
    "select-serial-port",
    (event, portList, webContents, callback) => {
      const newPortList: Electron.SerialPort[] = [];
      for (let port of portList) {
        if (port.portName.includes("COM")) {
          newPortList.push(port);
        }
      }

      mainWindow.webContents.send("portlist", newPortList);
    }
  );
};

// This method will be called when Electron has finished
// initialization and is ready to create browser windows.
// Some APIs can only be used after this event occurs.
app.on("ready", async () => {
  try {
    readFileSync("config.cnf").toString("utf-8");
  } catch {
    // file not found error
    writeFileSync("config.cnf", "API=http://localhost:3021/api/v1/");
  }

  ipcMain.handle("loadImg", (event, args) => {
    const ext = path.extname(args);
    try {
      const image = readFileSync(path.join(process.cwd(), "resources", args));
      return `data:image/${ext};base64,${image.toString("base64")}`;
    } catch {
      const image = readFileSync(path.join(process.cwd(), "public", args));
      return `data:image/${ext};base64,${image.toString("base64")}`;
    }
  });

  ipcMain.handle("uploadImg", async (event, args) => {
    event.preventDefault();
    var API = "";
    try {
      const config = readFileSync("config.cnf").toString("utf-8");
      for (let data of config.split("\n")) {
        if (data.includes("API")) {
          API = data.split("=")[1].trim().replaceAll('"', "");
          break;
        }
      }
    } catch {
      // file not found error
      writeFileSync("config.cnf", "API=http://localhost:3021/api/v1/");
      API = "http://localhost:3021/api/v1/";
    }

    const fileDialog = dialog.showOpenDialog({
      properties: ["openFile"],
      filters: [
        {
          name: "image/png,jpg,jpeg,bmp,webp",
          extensions: ["png", "jpg", "jpeg", "bmp", "webp"],
        },
      ],
    });
    if ((await fileDialog).canceled) return await fileDialog;
    const file = readFileSync((await fileDialog).filePaths[0]);
    const filePath = (await fileDialog).filePaths[0].split("\\");
    const formData = new FormData();
    formData.append(
      "file",
      new Blob([file], {
        type: `image/${
          path.extname(filePath[filePath.length - 1]).split(".")[1]
        }`,
      }),
      filePath[filePath.length - 1]
    );
    try {
      const res = await fetch(API + args.URL, {
        method: args.method,
        body: formData,
      });
      if (!res.ok) return await fileDialog;
      return file;
    } catch {
      return await fileDialog;
    }
  });

  ipcMain.handle("getImg", async (event, args) => {
    event.preventDefault();
    var API = "";
    try {
      const config = readFileSync("config.cnf").toString("utf-8");
      for (let data of config.split("\n")) {
        if (data.includes("API")) {
          API = data.split("=")[1].trim().replaceAll('"', "");
          break;
        }
      }
    } catch {
      // file not found error
      writeFileSync("config.cnf", "API=http://localhost:3021/api/v1/");
      API = "http://localhost:3021/api/v1/";
    }

    try {
      const res = await fetch(API + args.URL, {
        method: args.method,
        body: args.body,
      });
      if (!res.ok) return null;
      return await res.arrayBuffer();
    } catch {
      return null;
    }
  });

  ipcMain.handle("fetch", async (event, args) => {
    var API = "";
    try {
      const config = readFileSync("config.cnf").toString("utf-8");
      for (let data of config.split("\n")) {
        if (data.includes("API")) {
          API = data.split("=")[1].trim().replaceAll('"', "");
          break;
        }
      }
    } catch {
      // file not found error
      writeFileSync("config.cnf", "API=http://localhost:3021/api/v1/");
      API = "http://localhost:3021/api/v1/";
    }
    if (args.method === "POST") {
      try {
        const res = await fetch(API + args.URL, {
          method: "POST",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify({ ...args.body }),
        });
        if (!res.ok) return null;
        return await res.json();
      } catch {
        return null;
      }
    } else if (args.method === "GET") {
      try {
        const res = await fetch(API + args.URL, {
          method: "GET",
          headers: { "Content-Type": "application/json" },
        });
        if (!res.ok) return null;
        return await res.json();
      } catch {
        return null;
      }
    } else if (args.method === "PATCH") {
      try {
        const res = await fetch(API + args.URL, {
          method: "PATCH",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify({ ...args.body }),
        });
        if (!res.ok) return null;
        return await res.json();
      } catch {
        return null;
      }
    } else if (args.method === "PUT") {
      try {
        const res = await fetch(API + args.URL, {
          method: "PUT",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify({ ...args.body }),
        });
        if (!res.ok) return null;
        return await res.json();
      } catch {
        return null;
      }
    } else if (args.method === "DELETE") {
      try {
        const res = await fetch(API + args.URL, {
          method: "DELETE",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify({ ...args.body }),
        });
        if (!res.ok) return null;
        return await res.json();
      } catch {
        return null;
      }
    } else return null;
  });

  ipcMain.handle("getAPIPath", (event, args) => {
    var API = "";
    try {
      const config = readFileSync("config.cnf").toString("utf-8");
      for (let data of config.split("\n")) {
        if (data.includes("API")) {
          API = data.split("=")[1].trim().replaceAll('"', "");
          break;
        }
      }
    } catch {
      // file not found error
      writeFileSync("config.cnf", "API=http://localhost:3021/api/v1/");
      API = "http://localhost:3021/api/v1/";
    }
    return API;
  });

  ipcMain.on("setAPIPath", (event, path: string) => {
    if (!path.endsWith("/")) path += "/";
    let newConfig = "";
    try {
      const config = readFileSync("config.cnf").toString("utf-8");
      if (!config.includes("API")) throw new Error("Invalid config file.");
      for (let data of config.split("\n")) {
        if (data.includes("API")) {
          newConfig += `API=${path}\n`;
        } else {
          newConfig += data + "\n";
        }
      }
      writeFileSync("config.cnf", newConfig.substring(0, newConfig.length - 1));
    } catch {
      // file not found error
      writeFileSync("config.cnf", `API=${path}`);
    }
  });

  ipcMain.handle("getSeawardCOMPort", async (event, args) => {
    var COM: string | null;
    try {
      const config = readFileSync("config.cnf").toString("utf-8");
      for (let data of config.split("\n")) {
        if (data.includes("SeawardCOM")) {
          COM = data.split("=")[1].trim().replaceAll('"', "");
          break;
        }
      }
    } catch {
      // file not found error
      writeFileSync("config.cnf", "API=http://localhost:3021/api/v1/");
      COM = null;
    }
    return COM;
  });

  ipcMain.on("setSeawardCOMPort", async (event, port) => {
    let newConfig = "";
    try {
      const config = readFileSync("config.cnf").toString("utf-8");
      if (!config.includes("SeawardCOM")) newConfig += `SeawardCOM=${port}\n`;
      for (let data of config.split("\n")) {
        if (data.includes("SeawardCOM")) {
          newConfig += `SeawardCOM=${port}\n`;
        } else {
          newConfig += data + "\n";
        }
      }
      writeFileSync("config.cnf", newConfig.substring(0, newConfig.length - 1));
    } catch {
      // file not found error
      writeFileSync("config.cnf", "API=http://localhost:3021/api/v1/");
    }
  });

  ipcMain.handle(
    "sssTest",
    async (event, args: { script: string; COM: string }) => {
      writeFileSync("payload.scp", args.script);

      try{
        if (
          existsSync(path.join(process.cwd(), "resources", "ssscmdproto.exe"))
        ) {
          const result = await execAsync(
            `cmd /c ${path.join(
              process.cwd(),
              "resources",
              "ssscmdproto.exe"
            )} -${args.COM} ./payload.scp`
          );
          return result.stdout;
        } else {
          const result = await execAsync(
            `cmd /c ${path.join(
              process.cwd(),
              "src",
              "asset",
              "ssscmdproto.exe"
            )} -${args.COM} ./payload.scp`
          );
          return result.stdout;
        }
      }
      catch(err){
        return "error"
      }
    }
  );

  ipcMain.handle(
    "fakeSssTest",
    async (event, args: { script: string; COM: string }) => {
      writeFileSync("payload.scp", args.script);
      const type = args.script.includes("HIPOT")
        ? "HIPOT"
        : args.script.includes("EBOND")
        ? "EBOND"
        : args.script.includes("DCIR")
        ? "DCIR"
        : "PWRLK";

      const isWindows = process.platform === "win32";

      if (isWindows) {
        const exePath = existsSync(path.join(process.cwd(), "resources", "FAKEssscmdproto.exe"))
          ? path.join(process.cwd(), "resources", "FAKEssscmdproto.exe")
          : path.join(process.cwd(), "src", "asset", "FAKEssscmdproto.exe");
        const result = await execAsync(`cmd /c ${exePath} ${type}`);
        return result.stdout;
      } else {
        const pyPath = existsSync(path.join(process.cwd(), "resources", "FAKEssscmdproto.py"))
          ? path.join(process.cwd(), "resources", "FAKEssscmdproto.py")
          : path.join(process.cwd(), "src", "asset", "FAKEssscmdproto.py");
        const result = await execAsync(`python3 ${pyPath} ${type}`);
        return result.stdout;
      }
    }
  );

  createWindow();
});

// Quit when all windows are closed, except on macOS. There, it's common
// for applications and their menu bar to stay active until the user quits
// explicitly with Cmd + Q.
app.on("window-all-closed", () => {
  if (process.platform !== "darwin") {
    app.quit();
  }
});

app.on("activate", () => {
  // On OS X it's common to re-create a window in the app when the
  // dock icon is clicked and there are no other windows open.
  if (BrowserWindow.getAllWindows().length === 0) {
    createWindow();
  }
});

